CREATE OR REPLACE FUNCTION public.yorisou_jsonb_object_length(p jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE STRICT
AS $function$
  select count(*)::integer from jsonb_object_keys(p);
$function$;

