end $$;

CREATE OR REPLACE FUNCTION public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text, p_source text DEFAULT 'web'::text, p_intent_nonce uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner text; v_deleted timestamptz; v_prev uuid; v_id uuid; v_permit boolean;
        v_existing public.yorisou_interpretation_responses%rowtype;
begin
  select r.owner_account_id, r.deleted_at into v_owner, v_deleted
    from public.yorisou_assessment_results r where r.id = p_result_row_id;
  if not found then raise exception 'result_not_found'; end if;
  if v_deleted is not null then raise exception 'result_erased'; end if;
  if v_owner is null or v_owner <> p_owner_account_id then raise exception 'result_not_owned'; end if;

  if p_intent_nonce is not null then
    select * into v_existing from public.yorisou_interpretation_responses
     where result_row_id = p_result_row_id
       and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if found then
      if v_existing.response_type      is distinct from p_response_type
         or v_existing.corrected_result_id is distinct from p_corrected_result_id
         or v_existing.reason_code     is distinct from p_reason_code
         or v_existing.source          is distinct from p_source then
        raise exception 'interpretation_intent_conflict';
      end if;
      return v_existing.id;
    end if;
  end if;

  select id into v_prev from public.yorisou_interpretation_responses
   where result_row_id = p_result_row_id order by sequence_no desc limit 1;

  v_permit := p_response_type in ('confirmed','corrected');

  begin
    insert into public.yorisou_interpretation_responses
      (result_row_id, owner_account_id, response_type, corrected_result_id, reason_code,
       supersedes_response_id, recommendation_use_permitted, continuity_use_permitted, source,
       intent_nonce)
    values
      (p_result_row_id, p_owner_account_id, p_response_type, p_corrected_result_id, p_reason_code,
       v_prev, v_permit, v_permit, p_source, p_intent_nonce)
    returning id into v_id;
  exception when unique_violation then
    select * into v_existing from public.yorisou_interpretation_responses
     where result_row_id = p_result_row_id
       and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if not found then raise; end if;
    if v_existing.response_type      is distinct from p_response_type
       or v_existing.corrected_result_id is distinct from p_corrected_result_id
       or v_existing.reason_code     is distinct from p_reason_code
       or v_existing.source          is distinct from p_source then
      raise exception 'interpretation_intent_conflict';
    end if;
    return v_existing.id;
  end;

  return v_id;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text, p_reason_code text, p_source text, p_intent_nonce uuid) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text, p_reason_code text, p_source text, p_intent_nonce uuid) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text, p_reason_code text, p_source text, p_intent_nonce uuid) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text, p_reason_code text, p_source text, p_intent_nonce uuid) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_attempt_start(p_method_id text, p_method_version text, p_required_count integer, p_claim_token_hash text, p_entry_source text DEFAULT NULL::text, p_ttl_hours integer DEFAULT 72)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_claim_token_hash is null or length(p_claim_token_hash) < 32 then
    raise exception 'attempt_claim_token_required';
  end if;
  insert into public.yorisou_assessment_attempts
    (method_id, method_version, required_count, claim_token_hash, entry_source, expires_at)
  values
    (p_method_id, p_method_version, p_required_count, p_claim_token_hash, p_entry_source,
     now() + make_interval(hours => greatest(0, coalesce(p_ttl_hours, 72))))
  returning id into v_id;
  return v_id;
end;
$function$;

