  execute 'revoke all on function public.yorisou_attempt_start(p_method_id text, p_method_version text, p_required_count integer, p_claim_token_hash text, p_entry_source text, p_ttl_hours integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_attempt_start(p_method_id text, p_method_version text, p_required_count integer, p_claim_token_hash text, p_entry_source text, p_ttl_hours integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
