CREATE OR REPLACE FUNCTION public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows integer;
begin
  update public.yorisou_assessment_attempts a
     set answers = p_answers, answered_count = p_answered_count, updated_at = now()
   where a.id = p_attempt_id
     and a.status = 'in_progress'
     and (
       (a.owner_account_id is null and a.claim_token_hash is not null
        and a.claim_token_hash = p_claim_token_hash
        and (a.expires_at is null or a.expires_at > now()))   -- expiry enforced here
       or (a.owner_account_id is not null and a.owner_account_id = p_owner_account_id)
     );
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    -- Distinguish expiry so the UI can explain it rather than showing a generic failure.
    if exists (select 1 from public.yorisou_assessment_attempts a
                where a.id = p_attempt_id and a.owner_account_id is null
                  and a.expires_at is not null and a.expires_at <= now()) then
      raise exception 'attempt_expired';
    end if;
    raise exception 'attempt_not_found_or_not_writable';
  end if;
  return p_answered_count;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt public.yorisou_assessment_attempts%rowtype; v_existing uuid; v_result_row uuid;
begin
  -- CANONICAL ENVELOPE GUARD: exactly one key, exactly the approved version.
  if p_dimension_output is null
     or jsonb_typeof(p_dimension_output) <> 'object'
     or (select count(*) from jsonb_object_keys(p_dimension_output)) <> 1
     or p_dimension_output->>'v' is distinct from 'pds-v1' then
    raise exception 'assessment_persisted_envelope_invalid';
  end if;

  select * into v_attempt from public.yorisou_assessment_attempts a
   where a.id = p_attempt_id
     and (
       (a.owner_account_id is null and a.claim_token_hash is not null and a.claim_token_hash = p_claim_token_hash)
       or (a.owner_account_id is not null and a.owner_account_id = p_owner_account_id)
     )
   for update;
  if not found then raise exception 'attempt_not_found_or_not_writable'; end if;

  select r.id into v_existing from public.yorisou_assessment_results r where r.attempt_id = p_attempt_id;
  if v_existing is not null then return v_existing; end if;

  if v_attempt.owner_account_id is null
     and v_attempt.expires_at is not null and v_attempt.expires_at <= now() then
    raise exception 'attempt_expired';
  end if;
  if p_answered_count < v_attempt.required_count then raise exception 'attempt_incomplete_coverage'; end if;

  update public.yorisou_assessment_attempts
     set answers = p_answers, answered_count = p_answered_count,
         status = 'completed', completed_at = now(), updated_at = now()
   where id = p_attempt_id;

  insert into public.yorisou_assessment_results
    (attempt_id, owner_account_id, method_id, method_version, scoring_version,
     result_schema_version, result_id, overlay_id, dimension_output, original_result_id)
  values
    (p_attempt_id, v_attempt.owner_account_id, v_attempt.method_id, v_attempt.method_version,
     p_scoring_version, p_result_schema_version, p_result_id, p_overlay_id,
     p_dimension_output, p_result_id)
  returning id into v_result_row;
  return v_result_row;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt public.yorisou_assessment_attempts%rowtype;
        v_result uuid;
begin
  if p_owner_account_id is null or length(p_owner_account_id) = 0 then
    raise exception 'claim_owner_required';
  end if;

  select * into v_attempt from public.yorisou_assessment_attempts a
   where a.id = p_attempt_id for update;
  if not found then raise exception 'attempt_not_found'; end if;

  -- Already claimed by this same account -> idempotent success.
  if v_attempt.owner_account_id is not null then
    if v_attempt.owner_account_id = p_owner_account_id then
      select r.id into v_result from public.yorisou_assessment_results r where r.attempt_id = p_attempt_id;
      return v_result;
    end if;
    raise exception 'attempt_already_claimed_by_another_owner';
  end if;

  if v_attempt.claim_token_hash is null or v_attempt.claim_token_hash <> p_claim_token_hash then
    raise exception 'claim_token_invalid';
  end if;
  if v_attempt.expires_at is not null and v_attempt.expires_at < now() then
    raise exception 'claim_token_expired';
  end if;

  update public.yorisou_assessment_attempts
     set owner_account_id = p_owner_account_id,
         claimed_at       = now(),
         claim_token_hash = null,   -- single use
         expires_at       = null,   -- claimed attempts do not expire
         updated_at       = now()
   where id = p_attempt_id;

  update public.yorisou_assessment_results
     set owner_account_id = p_owner_account_id
   where attempt_id = p_attempt_id
  returning id into v_result;

  return v_result;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_attempt_abandon(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows integer;
begin
  if p_reason not in ('user_restarted','expired','erased') then
    raise exception 'attempt_abandon_reason_invalid';
  end if;
  update public.yorisou_assessment_attempts a
     set status = 'abandoned',
         answers = '{}'::jsonb,
         answered_count = 0,
         claim_token_hash = null,   -- the old credential can never be replayed
         completed_at = null,
         entry_source = p_reason,   -- bounded, non-identifying abandonment classification
         updated_at = now()
   where a.id = p_attempt_id
     and a.status = 'in_progress'
     and (
       (a.owner_account_id is null and a.claim_token_hash = p_claim_token_hash)
       or (a.owner_account_id is not null and a.owner_account_id = p_owner_account_id)
     );
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$function$;

