  execute 'revoke all on function public.yorisou_attempt_abandon(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_reason text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_attempt_abandon(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_reason text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_attempt_abandon(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_reason text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_attempt_abandon(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_reason text) to service_role';
  end if;
end $$;

