  ) then
    execute 'create trigger yorisou_interpretation_responses_no_update BEFORE DELETE OR UPDATE ON public.yorisou_interpretation_responses FOR EACH ROW EXECUTE FUNCTION yorisou_interpretation_responses_append_only()';
  end if;
end $$;

do $$ begin
  if not exists (
    select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
     where c.relname = 'yorisou_interpretation_responses' and t.tgname = 'yorisou_interpretation_supersedes_guard' and not t.tgisinternal
  ) then
    execute 'create trigger yorisou_interpretation_supersedes_guard BEFORE INSERT ON public.yorisou_interpretation_responses FOR EACH ROW EXECUTE FUNCTION yorisou_interpretation_supersedes_same_result()';
